package dev.materione.testing.golden;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;

/**
 * Golden-file support (D7: determinism makes golden tests sound). The corpus
 * lives in {@code fixtures/} at the repo root — data-only, never a Gradle
 * module, grows only (roadmap rule 2).
 *
 * <p>Regenerate a golden with {@code -Dmaterione.golden.regen=true} — review
 * the diff, then commit; goldens are never regenerated by CI.
 */
public final class GoldenFiles {

    private GoldenFiles() {}

    /** The fixtures root, injected as a system property by java-conventions. */
    public static Path fixturesRoot() {
        String root = System.getProperty("materione.fixtures.root");
        if (root == null || root.isBlank()) {
            throw new IllegalStateException(
                    "System property materione.fixtures.root not set — run via Gradle");
        }
        return Path.of(root);
    }

    public static Path golden(String relativeName) {
        return fixturesRoot().resolve("golden").resolve(relativeName);
    }

    public static boolean regenEnabled() {
        return Boolean.getBoolean("materione.golden.regen");
    }

    /** Writes (or overwrites) the golden from an actual file. */
    public static void writeGolden(Path actualFile, String goldenName) throws IOException {
        Path target = golden(goldenName);
        Files.createDirectories(target.getParent());
        Files.write(target, Files.readAllBytes(actualFile));
    }

    /**
     * Asserts an actual file matches its golden byte-for-byte.
     *
     * @throws AssertionError with a first-difference report on mismatch
     */
    public static void assertMatchesGolden(Path actualFile, String goldenName) throws IOException {
        byte[] actual = Files.readAllBytes(actualFile);
        byte[] expected = Files.readAllBytes(golden(goldenName));
        if (Arrays.equals(actual, expected)) {
            return;
        }
        int firstDiff = firstDifference(actual, expected);
        throw new AssertionError(
                "Golden mismatch: " + goldenName
                        + " — actual " + actual.length + " bytes, expected " + expected.length
                        + " bytes, first difference at byte " + firstDiff
                        + "\n  actual:   ..." + snippet(actual, firstDiff)
                        + "\n  expected: ..." + snippet(expected, firstDiff)
                        + "\n  If this change is intentional, regenerate with"
                        + " -Dmaterione.golden.regen=true and review the diff.");
    }

    private static int firstDifference(byte[] a, byte[] b) {
        int limit = Math.min(a.length, b.length);
        for (int i = 0; i < limit; i++) {
            if (a[i] != b[i]) {
                return i;
            }
        }
        return limit;
    }

    private static String snippet(byte[] bytes, int at) {
        int from = Math.max(0, at - 32);
        int to = Math.min(bytes.length, at + 32);
        return new String(bytes, from, to - from, java.nio.charset.StandardCharsets.UTF_8)
                .replace('\n', '\\');
    }
}
